package com.novacommerce.order.domain.cart; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="carts") public class Cart {@Id private UUID id;@Column(name="owner_id",nullable=false)private UUID ownerId;@Enumerated(EnumType.STRING)@Column(nullable=false)private CartStatus status;@Version private long version;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@ElementCollection(fetch=FetchType.EAGER)@CollectionTable(name="cart_items",joinColumns=@JoinColumn(name="cart_id"))private Set<CartItem> items=new LinkedHashSet<>();protected Cart(){}public Cart(UUID owner,Instant now){id=UUID.randomUUID();ownerId=owner;status=CartStatus.ACTIVE;createdAt=updatedAt=now;}public void add(UUID variant,long q,Instant now){CartItem found=items.stream().filter(i->i.getVariantId().equals(variant)).findFirst().orElse(null);if(found==null)items.add(new CartItem(variant,q,now));else found.setQuantity(Math.addExact(found.getQuantity(),q),now);updatedAt=now;}public void update(UUID variant,long q,Instant now){CartItem found=items.stream().filter(i->i.getVariantId().equals(variant)).findFirst().orElseThrow(()->new IllegalArgumentException("Cart item not found"));found.setQuantity(q,now);updatedAt=now;}public void remove(UUID variant,Instant now){items.removeIf(i->i.getVariantId().equals(variant));updatedAt=now;}public void clear(Instant now){items.clear();updatedAt=now;}public void beginCheckout(Instant now){if(status!=CartStatus.ACTIVE||items.isEmpty())throw new IllegalStateException("Cart cannot begin checkout");status=CartStatus.CHECKOUT_PENDING;updatedAt=now;}public void reopen(Instant now){if(status==CartStatus.CHECKOUT_PENDING){status=CartStatus.ACTIVE;updatedAt=now;}}public void convert(Instant now){if(status!=CartStatus.CHECKOUT_PENDING)throw new IllegalStateException("Cart is not pending checkout");status=CartStatus.CONVERTED;updatedAt=now;}public UUID getId(){return id;}public UUID getOwnerId(){return ownerId;}public CartStatus getStatus(){return status;}public long getVersion(){return version;}public Set<CartItem> getItems(){return Set.copyOf(items);}}
